mapper.select:
WITH doccs_doc AS ( SELECT document_id FROM nyehms_owner.std_din_doccs_doc WHERE doccs_doc_id IN
#{documentId}
), data AS ( SELECT MAX (a.date_of_death) dod, MAX(s.calc_collection_date) hiv_col_date, MAX(e.calc_collection_date) std_col_date FROM nyehms_owner.document_person_attr a, nyehms_owner. person_doc_association p, doccs_doc d, nyehms_owner.std_hiv_eclrs_doc s, nyehms_owner.std_std_eclrs_doc e WHERE a.document_id = p.document_id AND p.dissassociation_date IS NULL AND a.document_id = d.document_id(+) AND p.document_id = s.document_id(+) AND p.document_id = e.document_id(+) AND (a.document_id IN
#{documentId}
OR p.stateno = #{stateno_target}) ) SELECT 'Y' FROM data WHERE GREATEST(Nvl(hiv_col_date,To_Date('01/01/1900','MM/DD/YYYY')), Nvl(std_col_date,To_Date('01/01/1900','MM/DD/YYYY'))) > Nvl(dod,To_Date('12/31/2999','MM/DD/YYYY'))
